#                財團法人職業災害預防及重建中心監督及管理辦法（補題）
A = "OSH-83"
B = "OSH-84"
C = "OSH-87"
Q = [

# ===== OSH-83 職業災害預防及職業災害勞工重建補助辦法 =====
(A,"第1條",1,"職災預防重建補助-授權依據",
 "職業災害預防及職業災害勞工重建補助辦法係依據何項法律規定訂定？",
 ["依勞工職業災害保險及保護法第六十二條第三項規定訂定之","依勞工職業災害保險及保護法第六十六條第二項規定訂定之","依職業災害勞工保護法第十條第一項授權規定所訂定之辦法","依職業安全衛生法第六十二條第三項授權規定所訂定之辦法"],"a",
 "第1條：本辦法依勞工職業災害保險及保護法第六十二條第三項規定訂定。第2條並列舉補助事項共七款；第19條定明所需經費由勞工職業災害保險基金預算支應。",
 "Which statutory provision is the legal basis of these Regulations?",
 ["Article 62-3 of the Labor Occupational Accident Insurance and Protection Act","Article 66-2 of the Labor Occupational Accident Insurance and Protection Act","Article 10-1 of the Protection for Workers Incurring Occupational Accidents Act","Article 62-3 of the Occupational Safety and Health Act as separately enacted"],
 "Article 1 cites Article 62, paragraph 3 of the Act."),

(A,"第3條",3,"職災預防重建補助-申請程序",
 "受補助單位擬定實施計畫並填具申請書，應於何時提出？文件未備齊如何處理？計畫年度執行期間為何？",
 ["每年八月底前提出；未備齊者得通知限期補正，屆期未補正不予受理；執行期間為次年度一月一日至十二月三十一日","每年六月底前提出；未備齊者應逕予駁回而不得補正；執行期間為當年度七月一日至次年度六月三十日止","每年十月底前提出；未備齊者得通知限期補正，屆期未補正即予核定；執行期間為當年度一月一日至十二月底止","每年二月或七月底前提出；未備齊者由審查小組代為補齊；執行期間為次年度七月一日至十二月三十一日"],"a",
 "第3條第1項：受補助單位應於每年八月底前向中央主管機關提出實施計畫及申請書；第2項未備齊者得通知限期補正，屆期未補正不予受理；第3項年度執行期間為次年度一月一日至十二月三十一日。第2條第2項並定中央主管機關應於每年六月底前公告次年度重點及優先補助事項。",
 "When must the plan be filed, what if documents are incomplete, and what is the execution period?",
 ["By end of August; incomplete filings may be corrected within a set period, else rejected; execution runs the whole next year","By end of June; incomplete filings are rejected outright with no chance to correct; execution runs July to next June","By end of October; incomplete filings may be corrected, and if not corrected they are approved anyway; execution is that year","By end of February or July; the review panel completes the documents itself; execution runs July to December next year"],
 "Article 3, paragraphs 1 to 3."),

(A,"第5條",2,"職災預防重建補助-申請資格",
 "申請辦理職業災害預防宣導之受補助單位，應符合何種條件？",
 ["依法設立之勞工團體、雇主團體或職業災害勞工團體；主持人具安全衛生宣導實務經驗三年以上","依法設立之勞工團體、雇主團體或職業災害勞工團體；主持人具安全衛生宣導實務經驗五年以上","經本法認可之職能復健專業機構或醫療機構；主持人具職業醫學教學經驗三年或實務經驗五年","學術機構或從事職業災害研究之機構或團體；主持人須為助理教授以上教師並任教滿三年以上"],"a",
 "第5條：依第2條第1項第2款申請職業災害預防宣導者，須為依法設立之勞工團體、雇主團體或職業災害勞工團體等相關團體，且計畫主持人具從事職業安全衛生宣導實務工作經驗三年以上。第6條則另定職業災害勞工重建宣導之資格條件。",
 "What conditions apply to units applying for occupational accident prevention publicity subsidies?",
 ["A lawfully established labor, employer or occupational accident workers group; leader with 3 years of publicity experience","A lawfully established labor, employer or occupational accident workers group; leader with 5 years of publicity experience","A recognized occupational rehabilitation or medical institution; leader with 3 years teaching or 5 years practice","An academic body or occupational accident research institution; leader an assistant professor for over three years"],
 "Article 5."),

(A,"第6條",2,"職災預防重建補助-申請資格",
 "申請辦理職業災害勞工重建宣導之受補助單位，其機構及主持人條件為何？",
 ["依本法認可之職能復健專業機構、醫療機構或身心障礙者職業訓練機構；主持人具相關教學經驗三年或實務經驗五年","依本法認可之職能復健專業機構、醫療機構或身心障礙者職業訓練機構；主持人具相關教學經驗五年或實務經驗三年","依法設立之勞工團體、雇主團體或職業災害勞工團體等；主持人具職業安全衛生宣導實務工作經驗三年以上","學術機構、教學醫院或從事職業醫學研究之機構團體；主持人須擔任主治醫師二年以上或碩士學位滿三年"],"a",
 "第6條：機構須為依本法認可之職能復健專業機構及醫療機構、身心障礙者職業訓練機構，或依法認可辦理身心障礙者職業訓練之社會福利機構及醫療機構；主持人須具職能復健、職業重建或職業醫學相關教學經驗三年以上，或實務經驗五年以上。",
 "What are the conditions for units applying for reconstruction publicity subsidies?",
 ["A recognized occupational rehabilitation, medical or disability vocational training body; leader 3 years teaching or 5 practice","A recognized occupational rehabilitation, medical or disability vocational training body; leader 5 years teaching or 3 practice","A lawfully established labor, employer or occupational accident workers group; leader with 3 years of publicity practice","An academic body, teaching hospital or occupational medicine research unit; leader an attending physician for two years"],
 "Article 6."),

(A,"第7條",3,"職災預防重建補助-主持人資格",
 "申請職業傷病之調查研究或職業傷病診療研發運用補助者，其計畫主持人應具何種資格之一？",
 ["助理教授以上教師三年以上、擔任主治醫師二年以上，或碩士以上學位且從事職業傷病調查研究三年以上之醫事人員","助理教授以上教師五年以上、擔任主治醫師三年以上，或學士以上學位且從事職業傷病調查研究一年以上之醫事人員","副教授以上教師二年以上、擔任住院醫師二年以上，或博士以上學位且從事職業傷病調查研究五年以上之醫事人員","助理教授以上教師三年以上、擔任主治醫師五年以上，或碩士以上學位且從事職業重建服務工作十年以上之社工人員"],"a",
 "第7條：機構須為學術機構、團體、教學醫院或從事職業醫學相關研究之機構或團體；主持人資格為助理教授以上教師三年以上、擔任主治醫師二年以上，或碩士以上學位且從事職業傷病調查或研究工作三年以上之醫事人員。",
 "What qualifications may the project leader hold for occupational injury investigation or treatment research?",
 ["Assistant professor 3 years, attending physician 2 years, or a master's holder with 3 years of injury research work","Assistant professor 5 years, attending physician 3 years, or a bachelor's holder with 1 year of injury research work","Associate professor 2 years, resident physician 2 years, or a doctorate holder with 5 years of injury research work","Assistant professor 3 years, attending physician 5 years, or a master's holder with 10 years of social work practice"],
 "Article 7."),

(A,"第8條",2,"職災預防重建補助-主持人資格",
 "申請重返職場輔助設施研發推廣或重返職場相關研究補助者，其機構及主持人條件為何？",
 ["學術機構或從事職業重建、職業災害勞工重建服務之機構；主持人得為職業重建實務五年以上並有職務再設計經驗者","學術機構或從事職業重建、職業災害勞工重建服務之機構；主持人得為職業重建實務三年以上並有職務再設計經驗者","全國性醫學專科醫學會或設有醫學系之大學附設醫院；主持人須具主持醫師培訓能力並任教職滿三年以上者","依法設立之勞工團體或雇主團體等相關團體；主持人須具安全衛生宣導實務工作經驗三年以上並曾主持研究計畫"],"a",
 "第8條：依第2條第1項第5款或第6款申請者，機構須為學術機構或從事職業重建服務、職業災害勞工重建服務之機構；主持人資格之一為從事職業重建實務經驗五年以上，並有職務再設計實務工作經驗者。",
 "What conditions apply to applications for return-to-work assistive facility research and promotion?",
 ["An academic body or vocational reconstruction service unit; leader may have 5 years practice plus job redesign experience","An academic body or vocational reconstruction service unit; leader may have 3 years practice plus job redesign experience","A national specialty medical association or a university hospital; leader must be able to lead physician training courses","A lawfully established labor or employer group; leader must have three years of safety and health publicity practice"],
 "Article 8."),

(A,"第9條",2,"職災預防重建補助-申請限制",
 "受補助單位提出申請時，計畫主持人之件數限制及延續性申請案應如何辦理？",
 ["每一計畫主持人每年以申請一個計畫為限；延續性申請案應於首年提出總計畫目標及分年工作計畫，並分年申請","每一計畫主持人每年以申請三個計畫為限；延續性申請案應於末年提出總計畫目標及分年工作計畫，並一次申請","每一受補助單位每年以申請一個計畫為限；延續性申請案免提總計畫目標，僅需逐年檢附經費概算表提出申請","每一計畫主持人每年申請計畫數並無限制；延續性申請案應於首年提出總計畫目標，並於次年一次請領全部經費"],"a",
 "第9條第1項：每一計畫主持人每年以申請一個計畫為限。第2項：延續性申請案應於首年提出總計畫目標、分年工作計畫目標、各年度執行期間、工作項目及經費概算，並分年申請。",
 "How many projects may one project leader apply for, and how are multi-year applications handled?",
 ["One project per leader per year; multi-year cases file overall and annual goals in the first year and apply year by year","Three projects per leader per year; multi-year cases file overall and annual goals in the last year and apply at once","One project per applicant unit per year; multi-year cases need no overall goal, only an annual budget estimate table","No limit on the number per leader; multi-year cases file overall goals first year and draw all funds the next year"],
 "Article 9."),

(A,"第10條",2,"職災預防重建補助-審查",
 "中央主管機關受理補助申請案件後，其審查及核定程序為何？",
 ["先進行應備書件及資格之初審，再由其組成之補助審查小組審查，依審查結果核定金額並得分期撥款","由職災預防及重建中心進行初審，再報中央主管機關逕予核定金額，應一次全額撥款不得分期辦理","由地方主管機關進行書件初審，再由中央主管機關組成之評鑑作業小組審查，核定金額後應一次撥款","中央主管機關僅為形式審查，實質審查由立法院審議後核定金額，並由勞工保險局分期辦理撥款作業"],"a",
 "第10條：中央主管機關應先進行應備書件及資格之初審，並組成職業災害預防及職業災害勞工重建補助審查小組審查初審通過之案件，依審查結果核定補助金額，並得分期撥款。第18條並允許委託職災預防及重建中心或有關團體辦理審查及撥款。",
 "What is the review and approval procedure after an application is accepted?",
 ["A preliminary document and eligibility check, then a subsidy review panel; the amount is set and may be paid in instalments","The prevention and reconstruction center screens first, the ministry approves directly, and the full sum is paid at once","Local authorities screen documents, an evaluation task force reviews, and the approved amount is paid in a single sum","The ministry reviews form only, the Legislative Yuan decides the sum, and the insurer pays it out in instalments"],
 "Article 10."),

(A,"第11條",1,"職災預防重建補助-審查基準",
 "實施計畫之審查，應考量哪些事項？",
 ["應考量年度職業災害預防及職業災害勞工重建重點事項、經費及實施計畫預期效益","應考量申請單位過去三年受補助次數、員工人數及機構所在縣市之人口密度高低","應考量計畫主持人之學歷高低、任職年資及該單位前一年度財務報表之盈虧情形","應考量受補助單位設立年限、資本額大小及其是否曾受主管機關表揚或獎勵紀錄"],"a",
 "第11條：實施計畫之審查，應考量年度職業災害預防及職業災害勞工重建重點事項、經費及實施計畫預期效益。此與第2條第2項中央主管機關每年公告之重點及優先補助事項相呼應。",
 "What factors must be considered when reviewing an implementation plan?",
 ["The annual priority items for accident prevention and worker reconstruction, the funding, and the expected benefits","The number of past subsidies in three years, staff size, and the population density of the county where it is located","The academic degree of the project leader, years of service, and the profit or loss shown in last year's accounts","The years since the unit was established, its capital, and whether it has ever received official commendation"],
 "Article 11."),

(A,"第12條",2,"職災預防重建補助-期中期末審查",
 "中央主管機關就受補助單位所提實施計畫成果之審查，其方式與免辦情形為何？",
 ["得辦理期中及期末審查，方式包括書面、會議或實地查核；計畫期間未達六個月者免辦期中審查","得辦理期中及期末審查，方式包括書面、會議或實地查核；計畫期間未達三個月者免辦期中審查","應每季辦理審查一次，且一律以實地查核方式進行；計畫期間未達一年者均免辦理期中審查","僅得辦理期末審查且限於書面審查方式；計畫期間達六個月以上者始須另行辦理期中審查作業"],"a",
 "第12條第1項：中央主管機關得辦理期中及期末審查，並得以書面、會議或實地查核之方式進行。第2項：計畫期間未達六個月者，免辦理期中審查。第3項：得依審查結論核定調整工作項目及經費。",
 "How may interim and final reviews be conducted, and when is the interim review waived?",
 ["Interim and final reviews by document, meeting or on-site check; the interim review is waived if the plan runs under six months","Interim and final reviews by document, meeting or on-site check; the interim review is waived if the plan runs under three months","Reviews must be held quarterly and only by on-site inspection; interim review is waived whenever the plan runs under one year","Only a final review by document is allowed; an interim review is required only where the plan lasts six months or longer"],
 "Article 12."),

(A,"第13條",1,"職災預防重建補助-查核",
 "中央主管機關對受補助單位之實地訪查或帳目查核，受補助單位有何義務？",
 ["中央主管機關認有必要時得派員實地訪查或帳目查核，受補助單位應配合，不得規避、妨礙或拒絕","中央主管機關應每半年派員實地訪查一次，受補助單位得以營業秘密為理由拒絕提供帳冊及資料","中央主管機關僅得委託會計師查核帳目而不得派員訪查，受補助單位亦無提供相關文件資料之義務","中央主管機關須經受補助單位書面同意始得查核，受補助單位拒絕時應報請法院裁定後始得進行"],"a",
 "第13條：中央主管機關認有必要時，得派員就受補助單位進行實地訪查或帳目查核；受補助單位應配合提供所需之相關文件及資料，不得規避、妨礙或拒絕。違反者依第15條第1項第3款不予補助或撤銷廢止後令其限期返還。",
 "What duty does a subsidized unit have when on-site visits or account audits are conducted?",
 ["Where necessary the ministry may send staff to inspect or audit; the unit must cooperate and may not evade, obstruct or refuse","The ministry must inspect every six months; the unit may refuse to supply books and data by claiming trade secrets","The ministry may only hire accountants to audit and may not visit; the unit has no duty to supply documents or data","The ministry needs the unit's written consent to audit; if refused, it must obtain a court ruling before proceeding"],
 "Article 13."),

(A,"第15條",3,"職災預防重建補助-不予補助",
 "受補助單位有虛偽不實、未確實執行計畫或規避查核等情形時，中央主管機關得如何處理？",
 ["提供虛偽不實文件、未確實執行計畫、規避查核或其他違反本辦法者，得列為五年內不予補助之對象","提供虛偽不實文件、未確實執行計畫、規避查核或其他違反本辦法者，得列為三年內不予補助之對象","僅有提供虛偽不實文件之情形者始得撤銷補助並令其返還，其餘各種情形均僅得予以書面警告處分","有前述違反情形者應先處以罰鍰，並逕行移送司法機關偵辦，不得再令其限期返還已領取之補助款"],"a",
 "第15條第1項：有提供虛偽不實文件資料、未確實執行經核定之實施計畫、規避妨礙或拒絕查核、其他違反本辦法規定者，應不予補助；已補助者經撤銷或廢止後，以書面行政處分令其限期返還。第2項：得按情節輕重列為五年內不予補助之對象，涉及刑責者移送司法機關偵辦。",
 "What sanctions apply for false documents, failure to execute the plan, or evading audits?",
 ["Such units may be listed as ineligible for subsidies for five years, besides refusal and ordered repayment of funds","Such units may be listed as ineligible for subsidies for three years, besides refusal and ordered repayment of funds","Only false documents allow revocation and repayment; every other situation results merely in a written warning","A fine must first be imposed and the case sent to prosecutors; repayment of the subsidy can no longer be ordered"],
 "Article 15."),

(A,"第16條",2,"職災預防重建補助-地方機關",
 "直轄市、縣（市）主管機關申請補助及執行成果報備之規定為何？",
 ["得就本法第六十二條第一項第一款、第三款、第四款及第六款事項申請補助；並於年度終了後二十日內彙整成果報備查","得就本法第六十二條第一項第一款、第三款、第四款及第六款事項申請補助；並於年度終了後六十日內彙整成果報備查","得就本法第六十二條第一項各款事項全部申請補助；並應於每年六月底前彙整前一年度執行成果報請中央主管機關備查","僅得就職業災害預防宣導一款事項申請補助；並應於年度開始前二十日內提報實施計畫，經核定後始得辦理該項業務"],"a",
 "第16條第1項：直轄市、縣（市）主管機關辦理本法第62條第1項第1款、第3款、第4款及第6款事項，得向中央主管機關申請補助。第2項：經核定補助者，應於年度終了後二十日內彙整全年度執行成果，報中央主管機關備查。",
 "For which items may local authorities apply, and when must they report execution results?",
 ["For items 1, 3, 4 and 6 of Article 62-1 of the Act; results are compiled and filed within 20 days after the year ends","For items 1, 3, 4 and 6 of Article 62-1 of the Act; results are compiled and filed within 60 days after the year ends","For all items listed in Article 62-1 of the Act; the prior year results must be compiled and filed by end of June","Only for accident prevention publicity; the plan must be filed 20 days before the year starts and be approved first"],
 "Article 16."),

(A,"第17條",3,"職災預防重建補助-重建中心",
 "職災預防及重建中心經核定補助者，其提報義務及賸餘款處理為何？",
 ["應於每年一月底前提報次年度實施計畫、概算及前一年度業務執行報告；賸餘款除行政管理費用外應於年度終了前繳回","應於每年七月底前提報次年度實施計畫、概算及前一年度業務執行報告；賸餘款含行政管理費用均應於年度終了前繳回","應於每年一月底前提報當年度實施計畫及前三年業務執行報告；賸餘款得全數保留作為次年度營運及人事費用之支出","應於每年三月底前提報次年度實施計畫及經費概算；因故未能執行之補助經費得經中央主管機關同意後留用不必繳回"],"a",
 "第17條第2項：職災預防及重建中心經核定補助者，應於每年一月底前提報次年度實施計畫、概算及前一年度業務執行報告，送中央主管機關審核。第3項：執行補助經費除行政管理費用外，有賸餘或因故未能執行者，應於年度終了前辦理繳回。",
 "What must the prevention and reconstruction center submit, and how is surplus funding handled?",
 ["By end of January it files next year's plan, budget and last year's report; surplus other than admin costs is returned in-year","By end of July it files next year's plan, budget and last year's report; all surplus including admin costs is returned in-year","By end of January it files the current year plan and three years of reports; surplus may be kept for next year's operations","By end of March it files next year's plan and budget; unspent subsidy may be retained with the ministry's consent instead"],
 "Article 17."),

(A,"第18條",2,"職災預防重建補助-委託",
 "中央主管機關得委託職災預防及重建中心或有關團體辦理哪些事項？",
 ["得委託辦理申請案受理、實施計畫審核或審查、受補助單位實地訪查、帳目查核及撥款等事項","得委託辦理申請案之受理，但實施計畫審核審查、實地訪查及撥款均應由中央主管機關自行辦理","得委託全民健康保險特約醫療機構辦理受理、審查、帳目查核及撥款，並由其自行核定補助金額","得委託地方主管機關辦理撥款作業，其餘受理審查及查核事項應委由立法院指定之外部專家辦理"],"a",
 "第18條：中央主管機關得委託職災預防及重建中心或有關團體辦理申請案之受理、實施計畫之審核或審查、受補助單位之實地訪查或帳目查核及撥款等事項。第10條之初審與審查小組審查則為中央主管機關之權責架構。",
 "Which tasks may the ministry commission the center or relevant groups to perform?",
 ["Receiving applications, reviewing plans, on-site visits, account audits and disbursement of the subsidy funds","Only receiving applications; plan review, on-site visits and disbursement must all be handled by the ministry itself","Commissioning contracted health insurance hospitals to receive, review, audit, disburse and set subsidy amounts","Commissioning local authorities to disburse, with all other tasks given to outside experts named by the legislature"],
 "Article 18."),

(A,"第19條",1,"職災預防重建補助-經費來源",
 "本辦法所定補助事項所需經費，其來源為何？",
 ["由勞工職業災害保險基金之預算支應該等補助所需之經費","由職業災害勞工保護專款之預算支應該等補助所需之經費","由中央主管機關之公務預算全額支應該等補助所需之經費","由勞工保險基金與地方政府預算各半分攤該等補助之經費"],"a",
 "第19條：本辦法所定補助事項所需經費，由勞工職業災害保險基金預算支應。同屬勞工職業災害保險及保護法體系之直轄市及縣市政府辦理協助職業災害勞工重返職場補助辦法第27條亦為相同財源設計。",
 "What is the funding source for the subsidies under these Regulations?",
 ["The budget of the Labor Occupational Accident Insurance Fund covers all such subsidy expenditures","The budget of the special fund for protection of occupational accident workers covers such expenditures","The general government budget of the central competent authority covers all such subsidy expenditures","The Labor Insurance Fund and local government budgets each bear one half of the required expenditure"],
 "Article 19."),

(A,"第20條",1,"職災預防重建補助-書表格式",
 "本辦法所定各項書表格式，應由何機關定之？",
 ["由中央主管機關訂定本辦法所定之各項書表格式","由地方主管機關訂定本辦法所定之各項書表格式","由職災預防及重建中心訂定本辦法所定書表格式","由中央衛生福利主管機關訂定本辦法所定書表格式"],"a",
 "第20條：本辦法所定書表格式，由中央主管機關定之。第3條所列申請書應載事項共十款，其格式即依本條授權訂定。",
 "Which authority prescribes the forms required under these Regulations?",
 ["The central competent authority prescribes all forms required under these Regulations","The local competent authority prescribes all forms required under these Regulations","The prevention and reconstruction center prescribes the forms required under them","The central health and welfare authority prescribes the forms required under them"],
 "Article 20."),

(A,"第21條",1,"職災預防重建補助-施行日",
 "本辦法及其修正條文之施行日期為何？",
 ["本辦法自中華民國一百十一年五月一日施行；修正條文自發布日施行","本辦法自中華民國一百十一年一月一日施行；修正條文自發布日施行","本辦法自中華民國一百十三年五月一日施行；修正條文自公布三個月後施行","本辦法自發布日施行；修正條文自中華民國一百十二年一月一日起始施行"],"a",
 "第21條：本辦法自中華民國一百十一年五月一日施行，修正條文自發布日施行。此與勞工職業災害保險及保護法之施行日一致，同法系之財團法人職業災害預防及重建中心監督及管理辦法第17條亦同。",
 "When did these Regulations and their amendments take effect?",
 ["They took effect on 1 May 2022; amended articles take effect on the date of promulgation","They took effect on 1 January 2022; amended articles take effect on the date of promulgation","They took effect on 1 May 2024; amended articles take effect three months after promulgation","They took effect on promulgation; the amended articles took effect on 1 January 2023 instead"],
 "Article 21."),

# ===== OSH-84 職業災害預防補助辦法 =====
(B,"第1條",1,"職災預防補助-授權依據",
 "職業災害預防補助辦法之訂定依據為何？",
 ["依職業災害勞工保護法第十條規定訂定之補助辦法","依職業災害勞工保護法第二十條規定訂定之補助辦法","依勞工職業災害保險及保護法第十條規定訂定辦法","依職業安全衛生法第十條第二項規定訂定之補助辦法"],"a",
 "第1條：本辦法依職業災害勞工保護法第十條規定訂定。第2條並定明其適用範圍為本法第10條第1項第1款至第5款及第8款所定職業災害預防事項之補助。",
 "What is the legal basis of the Occupational Accident Prevention Subsidy Regulations?",
 ["Article 10 of the Protection for Workers Incurring Occupational Accidents Act","Article 20 of the Protection for Workers Incurring Occupational Accidents Act","Article 10 of the Labor Occupational Accident Insurance and Protection Act","Article 10, paragraph 2 of the Occupational Safety and Health Act as amended"],
 "Article 1."),

(B,"第3條",2,"職災預防補助-申請資格",
 "依本法第十條第一項第一款或第二款規定申請補助之單位，應符合何種條件？",
 ["為大專校院或從事職業災害研究之機構；主持人曾任教授、副教授或助理教授合計三年以上","為大專校院或從事職業災害研究之機構；主持人曾任教授、副教授或助理教授合計五年以上","為全國性醫學專科醫學會或設有醫學系之大學校院；主持人須具主持醫師培訓能力三年以上","為事業單位、職業訓練機構及相關團體；主持人具安全衛生教育訓練實務工作經驗五年以上"],"a",
 "第3條：申請單位須為大專校院或從事職業災害研究之機構，且計畫主持人具安全衛生相關教學研究經驗並曾任教授、副教授或助理教授合計三年以上，或相當等級之專業人員三年以上，並有主持職業災害研究或職業疾病防治規劃能力。",
 "What conditions apply to units applying under items 1 or 2 of Article 10-1 of the Act?",
 ["A college or occupational accident research institution; leader served as professor grades for three years total","A college or occupational accident research institution; leader served as professor grades for five years total","A national specialty medical association or a university with a medical department; leader trains physicians","A business entity, vocational training institution or related group; leader with five years training practice"],
 "Article 3."),

(B,"第4條",2,"職災預防補助-培訓醫師",
 "申請補助培訓職業疾病醫師之單位，應符合何種條件？",
 ["為全國性醫學專科醫學會或大學校院設有醫學系所並附設醫院開辦職業疾病門診；主持人具主持醫師培訓能力","為全國性護理人員相關學會或大專校院設有護理科系所；主持人具主持職業衛生護理人員培訓之能力者","為大專校院或從事職業災害研究之機構；主持人具安全衛生相關類科高等考試及格且實務經驗三年以上","為事業單位或職業訓練機構且訓練設施完善；主持人具安全衛生教育訓練實務工作經驗五年以上者"],"a",
 "第4條：申請補助培訓職業疾病醫師之單位，須為全國性醫學專科醫學會或大學校院設有醫學系、所並附設醫院開辦職業疾病門診，且計畫主持人具職業醫學相關教學研究經驗、曾任教授等職合計三年以上或相當等級專業人員三年以上，並有主持醫師培訓能力。",
 "What conditions apply to units applying for subsidies to train occupational disease physicians?",
 ["A national specialty medical association or a university medical department with a hospital occupational disease clinic","A national nursing association or a college with a nursing department; leader able to lead occupational nurse training","A college or occupational accident research institution; leader passed the senior exam with three years of practice","A business entity or vocational training institution with good facilities; leader with five years of training practice"],
 "Article 4."),

(B,"第5條",2,"職災預防補助-培訓護理人員",
 "申請補助培訓職業衛生護理人員之單位，應符合何種條件？",
 ["為全國性護理人員相關學（協）會或大專校院設有護理科、系、所；主持人具主持護理人員培訓能力","為全國性醫學專科醫學會或大學校院附設醫院開辦職業疾病門診；主持人具主持醫師培訓能力者","為大專校院或從事職業災害研究之機構；主持人具主持職業災害研究或職業疾病防治規劃之能力","為事業單位、職業訓練機構及相關團體且師資人力健全；主持人具安全衛生相關教學經驗三年以上"],"a",
 "第5條：申請補助培訓職業衛生護理人員之單位，須為全國性護理人員相關學（協）會或大專校院設有護理科、系、所，且計畫主持人具護理相關教學研究經驗、曾任教授等職合計三年以上或相當等級專業人員三年以上，並有主持職業衛生護理人員培訓能力。",
 "What conditions apply to units seeking subsidies to train occupational health nurses?",
 ["A national nursing association or a college with a nursing department; leader able to lead nurse training programs","A national specialty medical association or university hospital occupational disease clinic; leader trains doctors","A college or occupational accident research institution; leader able to lead research or disease prevention plans","A business entity, training institution or group with sound faculty; leader with three years teaching experience"],
 "Article 5."),

(B,"第6條",2,"職災預防補助-技術專業業務",
 "依本法第十條第一項第四款規定申請補助之單位，其計畫主持人資格為何？",
 ["安全衛生相關類科高等考試及格且實務經驗三年以上，或大專校院以上畢業且實務工作經驗五年以上","安全衛生相關類科普通考試及格且實務經驗五年以上，或高中職以上畢業且實務工作經驗三年以上","須曾任教授、副教授或助理教授合計三年以上，或相當等級之專業人員並具主持研究能力三年以上","須具有職業醫學相關教學研究經驗五年以上，或擔任職業醫學科專科醫師執業滿三年以上之醫師"],"a",
 "第6條：依本法第10條第1項第4款申請補助之單位，須從事相關技術性及專業性業務，且計畫主持人具安全衛生相關類科高等考試及格並具安全衛生實務經驗三年以上，或大專校院以上畢業且具安全衛生實務工作經驗五年以上。",
 "What qualifications must the project leader have under item 4 of Article 10-1 of the Act?",
 ["Passed the senior civil service exam with three years practice, or a college graduate with five years of practice","Passed the ordinary civil service exam with five years practice, or a high school graduate with three years work","Served as professor, associate or assistant professor for three years, or an equivalent professional at that level","Five years of occupational medicine teaching and research, or three years practising as an occupational physician"],
 "Article 6."),

(B,"第8條",1,"職災預防補助-宣導",
 "申請補助辦理勞工安全衛生宣導之單位，其計畫主持人應具備何種經驗？",
 ["應具有安全衛生宣導實務工作經驗三年以上者始得擔任該計畫主持人","應具有安全衛生宣導實務工作經驗五年以上者始得擔任該計畫主持人","應具有安全衛生相關教學經驗三年以上或研究工作經驗一年以上之人員","應具有職業醫學相關教學研究經驗並曾任助理教授以上職務三年以上者"],"a",
 "第8條：依本法第10條第1項第5款規定申請補助勞工安全衛生宣導之單位，其計畫主持人應具有安全衛生宣導實務工作經驗三年以上。第7條則規範教育訓練補助之單位條件，主持人須教學經驗三年或訓練實務五年以上。",
 "What experience must the project leader have for safety and health publicity subsidies?",
 ["At least three years of hands-on experience in safety and health publicity work is required","At least five years of hands-on experience in safety and health publicity work is required","At least three years of safety and health teaching or one year of research work is required","Occupational medicine teaching experience and three years as assistant professor or above"],
 "Article 8."),

(B,"第9條",2,"職災預防補助-申請期限",
 "申請補助之單位應於何時、向何機關提出申請？",
 ["應於每年二月或七月底前，向勞動部職業安全衛生署提出實施計畫書及申請書","應於每年八月底前，向勞動部職業安全衛生署提出實施計畫書及相關申請書","應於每年一月、四月、七月或十月，向當地勞工主管機關提出實施計畫書申請","應於每年十月底前，向勞動部勞工保險局提出實施計畫書及相關之申請書件"],"a",
 "第9條：申請補助之單位應依所定九項內容訂定實施計畫書並填具申請書（如附表），於每年二月或七月底前向勞動部職業安全衛生署提出。第2條第2項並定中央主管機關應於每年十月底前公告下年度職業災害預防重點及優先補助事項。",
 "By when and to whom must subsidy applications be submitted?",
 ["By the end of February or July each year, to the Occupational Safety and Health Administration of the Ministry","By the end of August each year, to the Occupational Safety and Health Administration of the Ministry of Labor","In January, April, July or October each year, to the local competent labor authority of that jurisdiction","By the end of October each year, to the Bureau of Labor Insurance of the Ministry of Labor for review"],
 "Article 9."),

(B,"第10條",2,"職災預防補助-申請限制",
 "申請補助單位提出申請之件數限制及延續性申請案之辦理方式為何？",
 ["每年各以一個計畫，且每一計畫主持人一次以申請一個計畫為限；延續性申請案應於首年提出總計畫目標並分年申請","每年各以三個計畫，且每一計畫主持人一次得申請二個計畫為限；延續性申請案應於末年提出總計畫目標一次申請","每年各以一個計畫為限，惟計畫主持人不受件數限制；延續性申請案免提分年工作計畫目標，逐年重新提出即可","每年申請件數並無限制，惟同一單位不得跨款項申請；延續性申請案應於首年一次請領各年度全部之補助經費"],"a",
 "第10條第1項：依本法第10條各款提出之申請，每年各以一個計畫，且每一計畫主持人一次以申請一個計畫為限。第2項：延續性申請案應於首年提出總計畫目標、分年工作計畫目標、各年度執行期間、工作項目及經費概算，並分年申請。",
 "What limits apply to the number of applications and how are multi-year cases handled?",
 ["One project per item per year and one project per leader at a time; multi-year cases file overall goals first and apply yearly","Three projects per item per year and two per leader; multi-year cases file overall goals in the final year and apply at once","One project per item yearly but no limit per leader; multi-year cases need no annual goals and are simply refiled each year","No limit on the number filed, but no cross-item filing; multi-year cases draw all years of funding in the first year at once"],
 "Article 10."),

(B,"第11條",2,"職災預防補助-審議",
 "職安署受理申請案件後之審核及報備查程序為何？",
 ["應依本辦法規定審核，並組成職業災害預防及重建補助審查委員會審議；每年二月底前將前一年度補助情形報備查","應依本辦法規定審核，並組成職業災害預防及重建補助審查委員會審議；每年六月底前將前一年度補助情形報備查","應逕送中央主管機關審核，並由中央主管機關組成審查小組審議；每年年底前將當年度補助情形公告於指定網站","應委由地方主管機關辦理初審後報核，並由審查委員會複審；每年三月底前將前一年度補助情形函報立法院審議"],"a",
 "第11條第1項：職安署受理申請案件應依本辦法規定審核。第2項：應組成職業災害預防及重建補助審查委員會予以審議，並於每年二月底前將前一年度補助情形報中央主管機關備查。",
 "What review and reporting steps apply after the OSHA receives applications?",
 ["It reviews per these Regulations and convenes a subsidy review committee; last year's subsidies are reported by end of February","It reviews per these Regulations and convenes a subsidy review committee; last year's subsidies are reported by end of June","It forwards cases to the ministry, which convenes a panel; that year's subsidies are published on the designated website","Local authorities screen first and the committee re-reviews; last year's subsidies go to the legislature by end of March"],
 "Article 11."),

(B,"第12條",1,"職災預防補助-補助額度",
 "職安署於審核申請單位之補助金額時，應考量哪些事項？",
 ["應考量年度職業災害預防重點事項、經費及實施計畫預期效益，決定補助之額度","應考量申請單位之資本額、員工人數及其所在地區之職業災害發生率高低情形","應考量計畫主持人之學歷、年資及該單位前一年度受補助款項之核銷比率高低","應考量申請單位設立年限長短、有無違規紀錄及其與職安署往來合作之次數"],"a",
 "第12條：職安署於審核申請單位之補助金額時，應考量年度職業災害預防重點事項、經費、實施計畫預期效益，決定補助額度。第2條第2項所公告之年度重點及優先補助事項即為此項考量之基準。",
 "What factors must be weighed when deciding the amount of subsidy?",
 ["The annual accident prevention priority items, the funding available, and the expected benefits of the plan","The applicant's capital, number of employees, and the occupational accident rate of the area it is in","The project leader's degree and seniority, and the settlement rate of the unit's subsidy in the prior year","How long the unit has existed, whether it has violations, and how often it has worked with the agency"],
 "Article 12."),

(B,"第13條",1,"職災預防補助-撥款",
 "職安署辦理補助款撥付及審查之方式為何？",
 ["得依實施計畫之特性分期辦理撥款，必要時得採期中及期末審查","得依實施計畫之特性分期辦理撥款，但一律不得辦理期中之審查","應於核定後一次全額撥款，並一律採期中及期末審查兩階段辦理","應於計畫完成核銷後始得撥款，必要時得採期初及期末審查方式"],"a",
 "第13條：職安署得依實施計畫之特性，分期辦理撥款，必要時得採期中及期末審查。第14條則規定計畫完成後三十日內送實施成果，經審查認定確依計畫執行後予以核銷，剩餘款應繳回。",
 "How may the OSHA disburse subsidy funds and conduct reviews?",
 ["It may disburse in instalments according to the plan's nature and hold interim and final reviews if needed","It may disburse in instalments according to the plan's nature but interim reviews are never permitted at all","It must disburse the whole sum at once after approval and always hold both interim and final reviews","It may disburse only after the plan is completed and settled, with initial and final reviews where needed"],
 "Article 13."),

(B,"第14條",2,"職災預防補助-核銷",
 "申請補助單位於實施計畫完成後，應於多久內辦理何項程序？剩餘款如何處理？",
 ["應於三十日內將實施成果及經費運用概況送職安署，經審查認定確依計畫執行後核銷，剩餘款應繳回","應於六十日內將實施成果及經費運用概況送職安署，經審查認定確依計畫執行後核銷，剩餘款應繳回","應於三十日內將實施成果送中央主管機關備查即完成核銷，剩餘款得留用於次年度之相同計畫支出","應於年度終了後二十日內彙整成果報職安署備查，經核定後撥付尾款，剩餘款免予繳回而得抵充經費"],"a",
 "第14條：申請補助單位於實施計畫完成後，應於三十日內將實施成果、補助經費運用概況及其他相關資料送職安署，經職安署審查認定受補助單位確依實施計畫執行後，予以核銷，如有剩餘款應繳回。",
 "Within what period must results be submitted after the plan ends, and what happens to surplus funds?",
 ["Within 30 days results and fund use must go to the OSHA; after review confirms execution it is settled and surplus returned","Within 60 days results and fund use must go to the OSHA; after review confirms execution it is settled and surplus returned","Within 30 days results are filed with the ministry for record, which completes settlement; surplus may be kept for next year","Within 20 days after the year ends results are filed; the balance is then paid and surplus need not be returned at all"],
 "Article 14."),

(B,"第15條",1,"職災預防補助-查訪",
 "中央主管機關及職安署對受補助單位辦理情形，得採取何種措施？",
 ["必要時得派員實地查訪受補助單位辦理情形，並得實施稽核及績效評估以落實計畫施行","必要時得函請受補助單位提出書面報告，但不得派員實地查訪亦不得辦理績效評估","應每季派員實地查訪一次並辦理績效評估，受補助單位得以營業秘密為由拒絕查核","應委託會計師事務所辦理稽核，主管機關本身不得派員實地查訪或實施績效之評估"],"a",
 "第15條：中央主管機關及職安署必要時，得派員實地查訪受補助單位辦理情形，並得實施稽核及績效評估，以落實計畫之施行。第16條則規定無故拒絕查核之法律效果。",
 "What measures may the ministry and the OSHA take regarding subsidized units?",
 ["Where necessary they may send staff for on-site visits and conduct audits and performance evaluations of the plan","Where necessary they may request written reports only, and may neither visit on site nor evaluate performance","They must visit quarterly and evaluate performance, but units may refuse checks by claiming trade secrets apply","They must commission accounting firms to audit, and may not themselves visit or evaluate performance at all"],
 "Article 15."),

(B,"第16條",2,"職災預防補助-罰則",
 "受補助單位未確實執行實施計畫或無故拒絕查核者，職安署得為何種處置？",
 ["得撤回補助並視情節輕重追回一部或全部補助款，並列為五年內不予補助之對象；涉刑責者移送偵辦","得撤回補助並視情節輕重追回一部或全部補助款，並列為三年內不予補助之對象；涉刑責者移送偵辦","僅得停止後續撥款而不得追回已撥付之補助款，並得列為次年度不予補助之對象；不生刑責移送問題","應先令其限期改善，屆期未改善者始得撤回補助，且無論情節輕重均應追回全部補助款並移送偵辦"],"a",
 "第16條：受補助單位未確實執行實施計畫或無故拒絕查核者，職安署得撤回補助，並視情節輕重得追回一部或全部補助款，並列為五年內不予補助之對象；如涉及刑責者，應移送司法機關偵辦。",
 "What may the OSHA do if a unit fails to execute the plan or refuses inspection without cause?",
 ["Withdraw the subsidy, recover part or all of it, bar the unit from subsidies for five years, and refer criminal cases","Withdraw the subsidy, recover part or all of it, bar the unit from subsidies for three years, and refer criminal cases","Only halt further payments without recovering sums paid, and bar the unit from subsidies for the following year","First order corrections within a period, then withdraw the subsidy and always recover the whole sum and refer it"],
 "Article 16."),

(B,"第17條",1,"職災預防補助-施行日",
 "職業災害預防補助辦法之施行日期規定為何？",
 ["本辦法自發布日施行，並未另定特別之施行日期","本辦法自中華民國一百十一年五月一日起始施行","本辦法自發布後六個月施行，並溯及既往適用之","本辦法自中華民國一百零三年一月一日起始施行"],"a",
 "第17條：本辦法自發布日施行。本辦法係依職業災害勞工保護法第10條訂定，與勞工職業災害保險及保護法體系下自一百十一年五月一日施行之職業災害預防及職業災害勞工重建補助辦法不同。",
 "When do these Regulations take effect?",
 ["They take effect on the date of promulgation, with no special date set","They take effect on 1 May 2022 under a specially designated schedule","They take effect six months after promulgation and apply retroactively","They take effect on 1 January 2014 under a specially designated date"],
 "Article 17."),

# ===== OSH-87 財團法人職業災害預防及重建中心監督及管理辦法 =====
(C,"第1條",1,"職災重建中心監管-授權依據",
 "財團法人職業災害預防及重建中心監督及管理辦法之訂定依據為何？",
 ["依勞工職業災害保險及保護法第七十二條第二項規定訂定之","依勞工職業災害保險及保護法第七十條第一項規定訂定之","依財團法人法第十九條第三項第二款規定所訂定之管理辦法","依職業災害勞工保護法第七十二條第二項規定所訂定之辦法"],"a",
 "第1條：本辦法依勞工職業災害保險及保護法第七十二條第二項規定訂定。該中心係依同法第七十條成立之財團法人，受勞動部監督及管理。",
 "What is the legal basis of these supervision and management Regulations?",
 ["Article 72, paragraph 2 of the Labor Occupational Accident Insurance and Protection Act","Article 70, paragraph 1 of the Labor Occupational Accident Insurance and Protection Act","Article 19, paragraph 3, subparagraph 2 of the Act Governing Incorporated Foundations","Article 72, paragraph 2 of the Protection for Workers Incurring Occupational Accidents Act"],
 "Article 1."),

(C,"第2條",2,"職災重建中心監管-監督事項",
 "職災預防及重建中心應就哪些事項受勞動部之監督及管理？",
 ["董事監察人遴聘比例資格、捐助章程變更程序、基金投資、財產管理、會計制度、預決算、績效評估及薪資獎金等","僅限於董事監察人之遴聘及捐助章程之變更程序二項事項，其餘財務及人事事項均由該中心董事會自行決定辦理","僅限於預算與決算之編審及核轉，以及年度績效評估三項事項，人事薪資與基金投資事項不在監督管理範圍內","僅限於基金投資項目及程序與財產之管理運用，其餘會計制度及董事監察人兼職費事項均由財團法人法逕行規範"],"a",
 "第2條：中心應就董事、監察人之遴聘比例及資格、捐助章程變更程序、設立基金投資項目及程序、財產管理及運用、會計制度、預決算之編審及核轉、績效評估、董事監察人兼職費、董事長執行長與其他從業人員之薪資及獎金、其他年度重大措施事項等十款，受勞動部監督及管理。",
 "Which matters are subject to the Ministry of Labor's supervision and management?",
 ["Board appointment and qualifications, charter amendment, fund investment, property, accounting, budgets, evaluation and pay","Only the appointment of directors and supervisors and the charter amendment procedure; all financial matters are internal","Only the preparation and forwarding of budgets and final accounts plus annual performance evaluation of the center's work","Only the fund's investment items and property management; accounting and concurrent-post fees fall outside supervision"],
 "Article 2."),

(C,"第4條",2,"職災重建中心監管-監察人",
 "職災預防及重建中心之監察人人數、性別比例及專長要求為何？",
 ["置監察人三人至五人，任一性別比例不得少於三分之一，均由本部遴聘，至少一人應具會計領域專長","置監察人三人至五人，任一性別比例不得少於五分之一，由董事會遴聘，至少二人應具會計領域專長","置監察人五人至七人，任一性別比例不得少於三分之一，均由本部遴聘，至少一人應具法律領域專長","置監察人三人至七人且人數應為單數，性別比例不設限制，由董事互選產生，並得指定常務監察人"],"a",
 "第4條：中心置監察人三人至五人，任一性別比例不得少於三分之一；監察人均由勞動部遴聘，並得互選其中一人為常務監察人；至少一人應具備會計領域專長。第3條則規定董事七人至十五人且人數應為單數。",
 "How many supervisors are appointed, and what gender and expertise requirements apply?",
 ["Three to five supervisors, neither gender under one third, all appointed by the Ministry, at least one with accounting expertise","Three to five supervisors, neither gender under one fifth, appointed by the board, at least two with accounting expertise","Five to seven supervisors, neither gender under one third, all appointed by the Ministry, at least one with legal expertise","Three to seven supervisors in an odd number, no gender rule, elected among directors, with a managing supervisor named"],
 "Article 4."),

(C,"第5條",3,"職災重建中心監管-章程變更",
 "職災預防及重建中心擬議變更捐助章程時，其決議門檻及會議程序有何要求？",
 ["應經全體董事三分之二以上出席、出席董事過半數同意後陳報本部許可；會議十日前通知，不得以臨時動議提出","應經全體董事過半數出席、出席董事三分之二以上同意後陳報本部許可；會議三日前通知，得以臨時動議提出","應經全體董事三分之二以上出席並全體同意後報本部備查即可；會議七日前通知，並得以臨時動議方式提出","應經董事會及監察人聯席會議過半數同意後逕行變更；會議三十日前通知，並應同時報請立法院審議通過"],"a",
 "第5條第1項：捐助章程變更之擬議應經全體董事三分之二以上出席，出席董事過半數同意通過後，陳報勞動部許可。第2項：召開該會議應於會議十日前將議程通知全體董事及勞動部，不得以臨時動議提出。",
 "What quorum and procedure apply to amending the endowment charter?",
 ["Two thirds of all directors present and a majority of those present, then reported to the Ministry; 10 days notice, no ad hoc motion","A majority of all directors present and two thirds of those present, then reported; three days notice and ad hoc motions allowed","Two thirds present and unanimous consent, then merely filed with the Ministry; seven days notice and ad hoc motions allowed","A majority at a joint board and supervisor meeting, then amended directly; 30 days notice and legislative approval as well"],
 "Article 5."),

(C,"第6條",3,"職災重建中心監管-基金投資",
 "職災預防及重建中心設立基金之投資，應符合何種規定及程序？",
 ["投資項目應符合財團法人法第十九條第三項第二款至第六款；投資計畫經董事會通過報本部核准後始得執行","投資項目應符合財團法人法第十九條第三項第一款至第三款；投資計畫經董事會通過報本部備查後即可執行","投資項目由董事會自行決定不受法律限制；投資計畫僅需送監察人查核，並於年度決算書中揭露即為已足","投資項目應符合證券投資信託及顧問法規定；投資計畫應報請立法院審議通過後，始得由中心對外進行投資"],"a",
 "第6條第1項、第2項：設立基金之投資項目應符合財團法人法第19條第3項第2款至第6款規定，且應擬具投資計畫經董事會通過並報勞動部核准後始得執行。第3項：投資計畫應包括投資金額、標的、資金運用方法、投資報酬、效益與風險分析及至少三年預估收支報表等。",
 "What rules and procedures govern investment of the center's endowment fund?",
 ["Items must fall within Article 19-3, subparagraphs 2 to 6 of the Foundations Act; the plan needs board passage and Ministry approval","Items must fall within Article 19-3, subparagraphs 1 to 3 of the Foundations Act; the plan needs board passage and mere filing","Items are freely decided by the board without legal limits; the plan goes only to supervisors and is disclosed in the accounts","Items must comply with the Securities Investment Trust Act; the plan must be approved by the Legislative Yuan beforehand"],
 "Article 6."),

(C,"第7條",1,"職災重建中心監管-財產管理",
 "職災預防及重建中心之財產管理及運用方法，應依何規定辦理？",
 ["除捐助章程另有規定外，應依財團法人法第十九條至第二十三條規定辦理","除捐助章程另有規定外，應依財團法人法第二十五條至第三十條規定辦理","一律應依預算法及決算法有關公有財產管理運用之規定辦理而無例外","一律由勞動部代為管理運用，中心本身不得自行處分其所有之財產"],"a",
 "第7條：中心之財產管理及運用方法，除捐助章程另有規定外，應依財團法人法第十九條至第二十三條規定辦理。第6條並就設立基金之投資另定應經董事會通過並報勞動部核准之程序。",
 "Which rules govern the management and use of the center's property?",
 ["Unless the endowment charter provides otherwise, Articles 19 to 23 of the Act Governing Incorporated Foundations apply","Unless the endowment charter provides otherwise, Articles 25 to 30 of the Act Governing Incorporated Foundations apply","The Budget Act and Final Accounts Act rules on public property management always apply without any exception at all","The Ministry of Labor manages the property on its behalf and the center may not dispose of any of its own property"],
 "Article 7."),

(C,"第8條",2,"職災重建中心監管-會計制度",
 "職災預防及重建中心之會計制度應如何建立？其內容架構為何？",
 ["應建立會計制度報本部核定；內容包括總說明、本文及附錄，本文並分列總則至附則等十一款事項","應建立會計制度報本部備查；內容包括總說明及本文二部分，附錄得視需要自行決定是否編列納入","應逕依商業會計法建立而免報主管機關；內容包括會計項目、簿籍及憑證三部分，不含內部審核處理","應由勞動部代為訂定並公告實施；內容包括財務報告、會計人員及會計檔案管理等三大部分之規定"],"a",
 "第8條第1項至第3項：中心應建立會計制度報勞動部核定；會計制度應包括總說明、本文及附錄；本文應包括總則、簿記組織系統圖、財務報告、會計項目、會計簿籍、會計憑證、會計事務之處理、內部審核之處理、會計檔案之管理、會計人員及附則等十一款。",
 "How must the center establish its accounting system and what does it comprise?",
 ["It must be established and submitted for Ministry approval; it comprises a summary, main text of eleven parts, and an appendix","It must be established and merely filed with the Ministry; it comprises a summary and main text, with an optional appendix","It follows the Business Accounting Act with no filing needed; it covers accounts, books and vouchers but not internal audit","The Ministry drafts and promulgates it for the center; it covers financial reports, accounting staff and archive management"],
 "Article 8."),

(C,"第10條",1,"職災重建中心監管-決算",
 "職災預防及重建中心之決算書內，應敘明及分析哪些事項？",
 ["應敘明預算所列工作計畫執行成果及評估其績效，並分析達成設立目的及捐助章程規定之情形","應敘明各項投資標的之市值變動及風險分析，並分析董事監察人出席會議之比率及其績效","應敘明年度員工薪資獎金支給總額及人數，並分析與本部所屬機關同職等人員待遇之差異","應敘明各項捐款來源及用途明細，並分析次年度預算編列之優先順序與零基預算之執行成效"],"a",
 "第10條第1項：中心應於決算書內敘明預算所列工作計畫執行成果及評估其績效，並分析達成設立目的及捐助章程規定之情形；第2項並定年度決算書格式如附件二。第11條則規定決算書之審定及送核轉期限。",
 "What must the center's final accounts statement set out and analyze?",
 ["Execution results of the budgeted work plan and its performance, plus analysis of fulfilling its purpose and charter","Market value changes and risk analysis of each investment, plus the attendance rate and performance of the board","Total salaries and bonuses paid and headcount, plus a comparison with pay of equivalent grades in the Ministry","Sources and uses of each donation received, plus the priority order and zero-based budgeting results for next year"],
 "Article 10."),

(C,"第11條",2,"職災重建中心監管-決算期限",
 "職災預防及重建中心之前一年度工作成果及決算書，應於何時、循何程序送出？",
 ["提經董事會審定並送全體監察人分別查核後，連同會計師查核報告，於每年三月三十一日前送本部核轉立法院審議","提經董事會審定並送常務監察人查核後，連同會計師查核報告，於每年七月十五日前送本部核轉立法院審議","經監察人查核後逕送本部備查即可，無須提經董事會審定，並應於每年四月三十日前完成送件之程序","提經董事會審定後送會計師查核，並於年度終了後二十日內送本部彙整，再由本部轉報行政院核定"],"a",
 "第11條：中心應依決算法及相關法令規定，將前一年度工作成果及決算書提經董事會審定，並送請全體監察人分別查核後，連同會計師查核報告，於每年三月三十一日前送勞動部核轉立法院審議。第9條之預算書則為每年七月十五日前送出。",
 "By when and through what steps must the prior year's results and final accounts be submitted?",
 ["Approved by the board and checked by all supervisors, then with the CPA report sent to the Ministry by 31 March for the legislature","Approved by the board and checked by the managing supervisor, then with the CPA report sent to the Ministry by 15 July","Checked by supervisors and filed directly with the Ministry without board approval, completed by 30 April each year","Approved by the board and audited by a CPA, then sent to the Ministry within 20 days after the year for Executive Yuan approval"],
 "Article 11."),

(C,"第12條",2,"職災重建中心監管-績效評估",
 "職災預防及重建中心之績效評估目標及結果，應於何時提報？本部得如何辦理評鑑？",
 ["應於每年四月三十日前提報董事會通過後送本部查核；本部得邀集勞雇團體代表及學者專家組成評鑑作業小組實地評鑑","應於每年一月三十一日前提報董事會通過後送本部查核；本部得邀集勞雇團體代表及學者專家組成評鑑作業小組實地評鑑","應於每年四月三十日前逕送本部備查而免經董事會通過；本部僅得以書面審查方式辦理，不得派員進行實地之評鑑作業","應於每年年度終了後二十日內提報監察人查核後送本部；本部應委託會計師事務所辦理評鑑，中心得拒絕不必要之查核"],"a",
 "第12條第1項：中心應於每年四月三十日前將當年度業務與財務運作績效評估目標及前一年度績效評估結果，提報董事會通過後送勞動部辦理查核。第2項：勞動部得邀集勞工團體代表、雇主團體代表、有關機關代表及學者專家組成評鑑作業小組進行實地評鑑。第3項：中心不得規避、妨礙或拒絕。",
 "When must performance evaluation targets and results be submitted, and how may the Ministry evaluate?",
 ["By 30 April after board approval, then filed for Ministry review; the Ministry may form an on-site evaluation task force","By 31 January after board approval, then filed for Ministry review; the Ministry may form an on-site evaluation task force","By 30 April sent straight to the Ministry without board approval; the Ministry may only review documents, never on site","Within 20 days after year end via supervisors; the Ministry must hire an accounting firm and the center may refuse checks"],
 "Article 12."),

(C,"第13條",2,"職災重建中心監管-兼職費",
 "職災預防及重建中心董事、監察人兼職費之支給規定為何？",
 ["軍公教人員依軍公教人員兼職費支給規定辦理，非軍公教人員得比照辦理；支給基準經董事會決議後報本部核准","軍公教人員依軍公教人員兼職費支給規定辦理，非軍公教人員一律不得支給任何兼職費用或出席費等給與","董事及監察人之兼職費一律不得支給，僅得依實報實銷方式支領出席會議所生之交通費及必要之膳雜費用","兼職費支給基準由本部逕行訂定並公告實施，中心董事會無權決議，變更時亦無須再報請本部核准後辦理"],"a",
 "第13條第1項：董事、監察人為軍公教人員者，其兼職費除法令另有規定外依軍公教人員兼職費支給規定辦理；非軍公教人員者得比照辦理。第2項：兼職費支給基準經董事會決議後應報勞動部核准，變更時亦同。",
 "How are concurrent-post fees for directors and supervisors regulated?",
 ["Public servants follow the official fee rules and others may follow them by analogy; the standard needs board and Ministry approval","Public servants follow the official fee rules, while non-public-servant directors may not receive any concurrent-post fee at all","No concurrent-post fee may be paid to any director or supervisor; only actual travel and meal costs may be reimbursed","The Ministry sets and announces the standard itself; the board has no say and changes need no further Ministry approval"],
 "Article 13."),

(C,"第14條",3,"職災重建中心監管-薪資上限",
 "職災預防及重建中心專任人員之薪資支給基準上限為何？超過上限時應如何處理？",
 ["董事長、執行長不超過本部部長待遇，副執行長及專業從業人員不超過比照簡任第十四職等政務次長待遇；超過者應報本部核准","董事長、執行長不超過行政院院長待遇，副執行長及專業從業人員不超過比照簡任第十二職等主任秘書待遇；超過者報本部備查","董事長、執行長不超過本部次長待遇，副執行長及專業從業人員不超過比照薦任第九職等科長待遇；超過者由董事會決議即可","董事長、執行長及全體從業人員均不得超過本部部長待遇；如有羅致不易之情形，得由中心逕行提高而不受任何上限限制"],"a",
 "第14條第3項：專任之董事長、執行長薪資不超過勞動部部長待遇；專任之副執行長、技術及其他專業從業人員不超過比照簡任第十四職等政務次長待遇。第4項：因羅致不易或具特殊專長而有超過上限需要者，應函報勞動部審查並經核准；第5項並得召集外部專家學者研商。",
 "What salary caps apply to the center's full-time senior staff, and what if they are exceeded?",
 ["Chairman and CEO no more than the Minister's pay, deputy CEO and professionals no more than a political deputy minister's; excess needs approval","Chairman and CEO no more than the Premier's pay, deputy CEO and professionals no more than a chief secretary's; excess is merely filed","Chairman and CEO no more than the Deputy Minister's pay, deputy CEO and professionals no more than a section chief's; board decides","Chairman, CEO and all staff are capped at the Minister's pay, but the center may raise it freely where recruitment proves difficult"],
 "Article 14."),

(C,"第15條",3,"職災重建中心監管-獎金",
 "職災預防及重建中心從業人員之獎金發放基準有何限制？",
 ["每人每年獎金總額以平均二點五個月薪給為原則，並得依個人績效訂差異化基準；基準應經董事會決議後報本部核准","每人每年獎金總額以平均三點五個月薪給為原則，並得依個人績效訂差異化基準；基準應經董事會決議後報本部備查","每人每年獎金總額以平均一點五個月薪給為上限，且不得訂定差異化之發放基準；基準由本部逕行訂定並公告實施","每人每年獎金總額並無月數限制，僅須在本部及所屬機關支給項目範圍內；基準由執行長核定後送董事會事後追認"],"a",
 "第15條第1項：獎金發放基準應在相當勞動部及所屬機關員工支給項目及基準範圍內訂定，提經董事會決議後報勞動部核准。第2項：每人每年獎金總額以平均二點五個月薪給為原則，並得依個人績效訂定差異化發放基準；符合但書所定敘年功俸已無級可晉且獎金最高為三點五個月者，得按人數比例調增平均月數。",
 "What limits apply to the center's bonus payment standards?",
 ["Bonuses average 2.5 months of pay per person per year with performance differentiation; the standard needs board and Ministry approval","Bonuses average 3.5 months of pay per person per year with performance differentiation; the standard needs board passage and filing","Bonuses are capped at 1.5 months per person per year with no differentiation allowed; the Ministry sets and announces the standard","No monthly cap applies so long as items match Ministry practice; the CEO approves the standard and the board ratifies it later"],
 "Article 15."),

(C,"第16條",2,"職災重建中心監管-自行辦理",
 "哪些業務職災預防及重建中心應自行辦理，不得委由其他機關（構）、團體為之？",
 ["本部委託行使公權力之事項，及其他經本部指定應自行辦理之事項，均應由中心自行辦理不得委外","僅本部委託行使公權力之事項應自行辦理，其餘經本部指定之事項均得視需要委由其他團體辦理","僅涉及補助費用審查及撥款之事項應自行辦理，本部委託行使公權力之事項得委由地方主管機關辦理","中心所有業務均得委由其他機關構或團體辦理，僅須事後將受託單位名冊及委辦內容函報本部備查"],"a",
 "第16條：本部委託行使公權力之事項及其他經本部指定應自行辦理之事項，職災預防及重建中心應自行辦理，不得委由其他機關（構）、團體為之。此與第2條第10款所定其他年度重大措施事項之監督範圍相配合。",
 "Which businesses must the center handle itself rather than commission out?",
 ["Matters of public authority entrusted by the Ministry and other matters the Ministry designates must be handled by the center","Only matters of public authority entrusted by the Ministry; other designated matters may be commissioned to outside groups","Only review and disbursement of subsidy funds; entrusted public authority matters may be given to local competent authorities","All of the center's business may be commissioned out, provided the list of contractors is later filed with the Ministry"],
 "Article 16."),

(C,"第17條",1,"職災重建中心監管-施行日",
 "財團法人職業災害預防及重建中心監督及管理辦法之施行日期為何？",
 ["本辦法自中華民國一百十一年五月一日施行","本辦法自中華民國一百十二年一月一日施行","本辦法自發布日施行，不另定特別施行日期","本辦法自中華民國一百十一年三月二十三日施行"],"a",
 "第17條：本辦法自中華民國一百十一年五月一日施行，與勞工職業災害保險及保護法及職業災害預防及職業災害勞工重建補助辦法之施行日相同。",
 "When did these Regulations take effect?",
 ["They took effect on 1 May 2022 as expressly provided","They took effect on 1 January 2023 as expressly stated","They took effect upon promulgation with no special date","They took effect on 23 March 2022 as expressly provided"],
 "Article 17."),
]
